# Starts the ASAA identity server (Keycloak) on 127.0.0.1:8280.
# Requires identity/.env with KC_BOOTSTRAP_ADMIN_PASSWORD set by the owner. The value is never printed.
#
# Client secrets for templates-web and portfolio-admin are generated by Keycloak on first import.
# Retrieve them only when needed: Keycloak admin console (http://127.0.0.1:8280), realm asaa,
# Clients, the client, Credentials tab. Do not copy them into any tracked file.

. (Join-Path $PSScriptRoot 'common.ps1')

$state = Get-BootstrapPasswordState
if ($state -ne 'ok') {
    Write-PasswordStateHelp $state
    Write-Host 'Stopped. Nothing was started.'
    exit 1
}

$code = Invoke-Compose 'up' '-d'
if ($code -ne 0) {
    Write-Host "docker compose up failed with exit code $code. Is Docker Desktop running?"
    exit $code
}
Write-Host 'Keycloak is starting on http://127.0.0.1:8280 (realm asaa). Run identity/scripts/status.ps1 to check it.'
exit 0
